    seen = set(keep)
    for r in range(height):
        for c in range(width):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            component = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                rr, cc = queue.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
